import type * as TRef from "../../TRef.js";
import * as Entry from "./entry.js";
import type * as TxnId from "./txnId.js";
export type Journal = Map<TRef.TRef<any>, Entry.Entry>;
export type Todo = () => unknown;
export type JournalAnalysis = JournalAnalysisInvalid | JournalAnalysisReadWrite | JournalAnalysisReadOnly;
export declare const JournalAnalysisInvalid: "Invalid";
export type JournalAnalysisInvalid = typeof JournalAnalysisInvalid;
export declare const JournalAnalysisReadWrite: "ReadWrite";
export type JournalAnalysisReadWrite = typeof JournalAnalysisReadWrite;
export declare const JournalAnalysisReadOnly: "ReadOnly";
export type JournalAnalysisReadOnly = typeof JournalAnalysisReadOnly;
export declare const commitJournal: (journal: Journal) => void;
export declare const analyzeJournal: (journal: Journal) => JournalAnalysis;
export declare const prepareResetJournal: (journal: Journal) => () => void;
export declare const collectTodos: (journal: Journal) => Map<TxnId.TxnId, Todo>;
export declare const execTodos: (todos: Map<TxnId.TxnId, Todo>) => void;
export declare const addTodo: (txnId: TxnId.TxnId, journal: Journal, todoEffect: Todo) => boolean;
export declare const isValid: (journal: Journal) => boolean;
export declare const isInvalid: (journal: Journal) => boolean;
